(function(){'use strict';const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;const stages=[...document.querySelectorAll('#analysis-stages li')];const progress=document.getElementById('analysis-progress');const decision=document.getElementById('hero-decision');const replay=document.getElementById('replay-analysis');let timers=[];function show(i){stages.forEach((s,n)=>s.classList.toggle('is-active',n<=i));progress.style.width=((i+1)/stages.length*100)+'%';if(i===stages.length-1){decision.className='decision decision--verify';decision.querySelector('.decision__icon').textContent='!';decision.querySelector('strong').textContent='Verify in app'}}function run(){timers.forEach(clearTimeout);timers=[];stages.forEach((s,i)=>s.classList.toggle('is-active',i===0));progress.style.width=reduced?'100%':'25%';decision.className='decision';decision.querySelector('.decision__icon').textContent='···';decision.querySelector('strong').textContent='Analyzing transaction';if(reduced){show(stages.length-1);return}stages.slice(1).forEach((_,i)=>timers.push(setTimeout(()=>show(i+1),(i+1)*800)))}if(replay&&stages.length){replay.addEventListener('click',run);run()}
const form=document.getElementById('impact-calculator');const fmt=new Intl.NumberFormat('en-US',{maximumFractionDigits:0});const usd=new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0});function value(id){const f=document.getElementById(id),v=Number(f.value);return Number.isFinite(v)?Math.min(Number(f.max),Math.max(Number(f.min),v)):Number(f.min)}function calculate(){const avoided=value('monthly-transactions')*value('review-rate')/100*value('false-decline-rate')/100*value('improvement-rate')/100;const calls=avoided*.6;document.getElementById('result-declines').textContent=fmt.format(avoided);document.getElementById('result-calls').textContent=fmt.format(calls);document.getElementById('result-hours').textContent=fmt.format(calls*8/60);document.getElementById('result-value').textContent=usd.format(calls*6)}if(form){form.addEventListener('input',calculate);calculate()}})();
